import{_ as s,o as a,c as e,a5 as n}from"./chunks/framework.D_J2JZBr.js";const k=JSON.parse('{"title":"参与共建","description":"从报告问题、网页纠错到本地预览、组件复用和 PR，参与维护有来源、尊重隐私的上科大芯知库。","frontmatter":{"title":"参与共建","description":"从报告问题、网页纠错到本地预览、组件复用和 PR，参与维护有来源、尊重隐私的上科大芯知库。"},"headers":[],"relativePath":"community/contributing.md","filePath":"community/contributing.md","lastUpdated":1795531638000}'),t={name:"community/contributing.md"};function l(h,i,p,o,d,c){return a(),e("div",null,[...i[0]||(i[0]=[n(`<h1 id="参与共建" tabindex="-1">参与共建 <a class="header-anchor" href="#参与共建" aria-label="Permalink to &quot;参与共建&quot;">​</a></h1><p>仓库：<a href="https://github.com/ShanghaiTech-IC-Wiki-Dev/shanghaitech-ic-wiki-dev.github.io" target="_blank" rel="noreferrer">ShanghaiTech-IC-Wiki-Dev/shanghaitech-ic-wiki-dev.github.io</a>。修正一处错字、补充一条引用、撰写一段带年份的实践经验，都是本项目欢迎的贡献。协作时请遵守<a href="https://github.com/ShanghaiTech-IC-Wiki-Dev/shanghaitech-ic-wiki-dev.github.io/blob/main/CODE_OF_CONDUCT.md" target="_blank" rel="noreferrer">社区行为准则</a>；更完整的命令与审核标准见<a href="https://github.com/ShanghaiTech-IC-Wiki-Dev/shanghaitech-ic-wiki-dev.github.io/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">仓库贡献指南</a>。</p><h2 id="报告问题或推荐资源" tabindex="-1">报告问题或推荐资源 <a class="header-anchor" href="#报告问题或推荐资源" aria-label="Permalink to &quot;报告问题或推荐资源&quot;">​</a></h2><p>在<a href="https://github.com/ShanghaiTech-IC-Wiki-Dev/shanghaitech-ic-wiki-dev.github.io/issues/new/choose" target="_blank" rel="noreferrer">创建议题</a>中选择错误反馈、资源推荐、内容投稿或功能建议，给出涉及的页面、原始来源，以及希望解决的问题。开始长篇投稿前，可以先到<a href="https://github.com/ShanghaiTech-IC-Wiki-Dev/shanghaitech-ic-wiki-dev.github.io/issues" target="_blank" rel="noreferrer">现有议题</a>查看是否有人正在整理同一主题。没有 Git 经验也可以只提交议题，由维护者协助整理。</p><h2 id="直接在网页上修改" tabindex="-1">直接在网页上修改 <a class="header-anchor" href="#直接在网页上修改" aria-label="Permalink to &quot;直接在网页上修改&quot;">​</a></h2><ol><li>打开目标文章，点击页面底部的“在 GitHub 上编辑此页”，进入该页面的源文件。</li><li>登录 GitHub，按提示 Fork（派生）仓库，在新分支上修改 Markdown，用预览查看标题、列表与链接。</li><li>保存到自己的分支，向上游仓库的 <code>main</code> 发起 Pull Request（合并请求），说明改动理由并附上资料来源。</li><li>查看 <strong>Checks</strong> 中的构建检查和维护者反馈。需要补充时继续向同一分支提交；合并后网站自动发布。</li></ol><h2 id="本地预览" tabindex="-1">本地预览 <a class="header-anchor" href="#本地预览" aria-label="Permalink to &quot;本地预览&quot;">​</a></h2><p>准备 Git 与 Node.js 22（含 npm），将自己的 Fork 克隆到本地后执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FORK_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ic-wiki</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ic-wiki</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>浏览器打开终端显示的本地地址，保存 Markdown 后页面自动刷新。提交前运行一次 <code>npm run build</code>：它与 PR 检查使用同一命令，遇到死链、Markdown 或 Vue 模板错误时会失败。依赖安装失败先核对 Node.js 版本与 npm 报错。</p><h2 id="目录结构与修改入口" tabindex="-1">目录结构与修改入口 <a class="header-anchor" href="#目录结构与修改入口" aria-label="Permalink to &quot;目录结构与修改入口&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/</span></span>
<span class="line"><span>  index.md                 首页</span></span>
<span class="line"><span>  explore-ic/              认识 IC：科普基础、知识地图与 research-directions/ 科研方向</span></span>
<span class="line"><span>  learning/                学习地图：基础知识与五个专业方向的路线和自学资源</span></span>
<span class="line"><span>  shanghaitech/            上科大 IC：courses/ 课程、faculty/ 教师、research-groups/ 课题组与平台、荣誉与培养项目</span></span>
<span class="line"><span>  research/                科研探索：进组、读论文、会议期刊、工具与写作</span></span>
<span class="line"><span>  competitions/            竞赛与项目：赛事指南、参赛经验、工程项目</span></span>
<span class="line"><span>  career/                  升学与职业：国内外升学、实习与就业</span></span>
<span class="line"><span>  tools/                   工具与资源：EDA 工具、开发环境、开源项目、友链</span></span>
<span class="line"><span>  community/               社区与共建：关于本站与贡献指南</span></span>
<span class="line"><span>  public/                  公开静态资源（public/assets/credits.txt 记录第三方作品署名）</span></span>
<span class="line"><span>  .vitepress/</span></span>
<span class="line"><span>    config.mts             导航、侧边栏与站点配置</span></span>
<span class="line"><span>    data/</span></span>
<span class="line"><span>      faculty.ts           教授与课题组数据</span></span>
<span class="line"><span>      courses.ts           课程数据</span></span>
<span class="line"><span>      directions.ts        研究方向分类</span></span>
<span class="line"><span>    theme/                 主题与全局组件</span></span></code></pre></div><p>先改已有页面，避免把同一份教授或课程表复制到多个地方。静态资源只提交有公开授权、体积适当且确实使用的文件，不上传个人备份、完整工具安装包或实验输出目录。</p><h3 id="新增页面与侧边栏" tabindex="-1">新增页面与侧边栏 <a class="header-anchor" href="#新增页面与侧边栏" aria-label="Permalink to &quot;新增页面与侧边栏&quot;">​</a></h3><p>先确认主题是否已有承载页面。新增页面放在对应板块，使用稳定的简短文件名；目录首页为 <code>index.md</code>，站内链接用绝对路径且不带 <code>.md</code>。例如 <code>docs/explore-ic/research-directions/eda.md</code> 对应 <code>/explore-ic/research-directions/eda</code>。</p><p>在 <code>docs/.vitepress/config.mts</code> 的 <code>sidebar</code> 中找到对应路径分组，沿用已有 <code>items</code> 写法加入条目，例如：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EDA 与设计自动化&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">link</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/explore-ic/research-directions/eda&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>这是既有路径的写法示例，不应再重复新增同名条目。全新路径先与维护者确认，并同步相关总览入口；若需要新增板块，再讨论导航，避免个人 PR 擅自重排全站结构。</p><h3 id="修改教授、课程与方向数据" tabindex="-1">修改教授、课程与方向数据 <a class="header-anchor" href="#修改教授、课程与方向数据" aria-label="Permalink to &quot;修改教授、课程与方向数据&quot;">​</a></h3><p>教授事实集中修改 <code>docs/.vitepress/data/faculty.ts</code>，课程事实集中修改 <code>courses.ts</code>，方向分类在 <code>directions.ts</code>。沿用文件内接口、字段和标识符，附官方来源与核实年份。教师研究方向应尽量忠于公开介绍，不从论文标题推断新职称或实验室名称。</p><p>修改课程时核对课程代码、学分、先修、开课学期和当年教师，不用往届笔记覆盖新学年开课表。新增方向属于跨页面变更，应同时检查方向数据中的链接、对应页面及组件使用；不要只新增一个标签。不会改 TypeScript 时，可在 Issue 中给出准确条目和来源，请维护者处理。</p><h2 id="写作规范摘要" tabindex="-1">写作规范摘要 <a class="header-anchor" href="#写作规范摘要" aria-label="Permalink to &quot;写作规范摘要&quot;">​</a></h2><ul><li>简体中文，标题不加 emoji；专业术语首次出现尽量给出英文，中英文及数字之间加空格。</li><li>frontmatter 只写 <code>title</code> 与 <code>description</code>，正文一级标题与 title 一致；通常以 800–3000 汉字讲清楚，不为凑字数堆材料。</li><li>优先写上科大独有信息；通用知识精炼说明并给可靠入口，不复制他站全文。</li><li>本校事实来自官方培养方案、开课表、师资库、课题组主页及正式通知；写清年份、适用项目和来源。不确定就省略或注明以官网为准。</li><li>经验与事实分开。往届经验注明学期版本，并提醒以当学期课程大纲为准，不写教师性格评价或未经核实的传闻。</li><li>站内链接使用已规划、实际存在的页面；外链优先官网，深层地址需现场核实。上科大特色页面末尾增加“参考与来源”。</li><li>不在普通 Markdown 正文写可能被 Vue 解释的双花括号插值或裸 HTML 片段；展示组件语法请放代码块。公式、代码与图表的写法见<a href="/shanghaitech-ic-wiki-dev.github.io/community/writing">文章写作示例</a>。</li></ul><h2 id="可复用组件与容器" tabindex="-1">可复用组件与容器 <a class="header-anchor" href="#可复用组件与容器" aria-label="Permalink to &quot;可复用组件与容器&quot;">​</a></h2><p>教授和课程信息使用全局组件，不再手写重复大表。以下语法放入正文即可使用：</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">FacultyList</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> dir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eda&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">FacultyList</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> dir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;digital&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> primary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">CourseTable</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> area</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;digital&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">CourseTable</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> codes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;EE115B,EE113,EE291F&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p><code>FacultyList</code> 不写 <code>dir</code> 时显示全部；<code>primary</code> 只显示主方向。方向 ID 为 <code>devices</code>、<code>photonics</code>、<code>mems</code>、<code>analog</code>、<code>power</code>、<code>rf</code>、<code>digital</code>、<code>ai-hw</code>、<code>arch</code>、<code>security</code>、<code>eda</code>。</p><p><code>CourseTable</code> 的 <code>area</code> 可选 <code>basic</code>、<code>digital</code>、<code>arch</code>、<code>ai</code>、<code>analog</code>、<code>rf</code>、<code>power</code>、<code>device</code>、<code>photonics</code>、<code>mems</code>、<code>eda</code>；注意课程与教授的相关 ID 并不完全同名。<code>codes</code> 必须与数据文件中的课程代码完全一致。<code>&lt;CourseTable filter /&gt;</code> 仅用于课程总览；<code>&lt;TopologyGraph /&gt;</code> 仅用于科研方向总览，不在其他页面复制交互拓扑。</p><p>经验征集统一使用下面的容器，每页通常一处即可：</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::: info 征集</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">欢迎通过[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">参与共建</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">/community/contributing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)补充注明年份的公开经验。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:::</span></span></code></pre></div><p>提示、重要限制和补充内容可用 <code>tip</code>、<code>warning</code>、<code>details</code> 容器。关系图用 Mermaid，节点不超过 25 个，特殊字符标签加双引号；图应帮助理解关系，不只用于装饰。</p><h2 id="内容模板" tabindex="-1">内容模板 <a class="header-anchor" href="#内容模板" aria-label="Permalink to &quot;内容模板&quot;">​</a></h2><p>新增页面可从仓库 <a href="https://github.com/ShanghaiTech-IC-Wiki-Dev/shanghaitech-ic-wiki-dev.github.io/tree/main/templates" target="_blank" rel="noreferrer"><code>templates/</code></a> 中复制最接近的一份：课程、课题组、研究方向、学习路线和经验分享。复制到对应板块后，删除模板中的提示文字，再按上文加入侧边栏。没有证据的事实不要补猜测，不把空白模板当成正文提交。</p><h2 id="pr-流程" tabindex="-1">PR 流程 <a class="header-anchor" href="#pr-流程" aria-label="Permalink to &quot;PR 流程&quot;">​</a></h2><ol><li>Fork 仓库并创建聚焦单一主题的分支；小改动也可从 GitHub 网页端发起。</li><li>编辑页面或集中数据，附来源、年份与必要的适用范围。</li><li>运行 <code>npm run build</code>，在本地预览检查标题、表格、容器、公式、图和链接；涉及组件或配置时说明影响范围。</li><li>按 PR 模板写清改了什么、为什么改、事实来源和实际做过的检查。未运行的检查如实注明，并查看 <strong>Checks</strong> 中 <strong>docs-build</strong> 的结果。</li><li>根据评审修改，保持 PR 只包含相关文件，不夹带缓存、依赖目录、构建产物和个人配置。合并后由部署工作流发布。</li></ol><h2 id="隐私、版权与事实核查" tabindex="-1">隐私、版权与事实核查 <a class="header-anchor" href="#隐私、版权与事实核查" aria-label="Permalink to &quot;隐私、版权与事实核查&quot;">​</a></h2><p>不公开学生姓名、成绩、学号、账号密码、私人邮箱、聊天记录、内网地址和未授权录音；不披露未发表论文、保密网表、PDK、商业软件许可或企业数据。教授仅写公开学术信息，不评价“好不好进组”等个人印象。</p><p>截图上传前检查边缘、文件路径和通知栏；打码不充分时宁可重做一张公开示意图。发现敏感内容应联系维护者处理，不在公开 Issue 中再次传播原文。转载前核对独立许可，本站的 CC BY 4.0 不会覆盖第三方材料；引用、翻译或改编须保留作者、原始出处、许可及修改说明。</p><p>AI 可以辅助整理公开材料与语言，但贡献者必须核对原文、链接和数字，不能用生成内容充当来源。提交原创文字意味着同意按<a href="/shanghaitech-ic-wiki-dev.github.io/community/">本站许可证说明</a>分享，并确认有权投稿；不清楚授权时只提供原始链接与自己的简短说明。</p>`,39)])])}const g=s(t,[["render",l]]);export{k as __pageData,g as default};
